let input=$input.first().json; if(input.payload) input=typeof input.payload==='string'?JSON.parse(input.payload):input.payload; if(input.body) input=input.body;
const required=['projectId','incidentId','fixRequestId','repository','prNumber','buildNumber','jenkinsJob','jenkinsStatus']; const missing=required.filter(k=>input[k]===undefined||input[k]===null||input[k]===''); if(missing.length) throw new Error('INVALID_VALIDATION_CONTRACT:'+missing.join(','));
const repository=String(input.repository).replace(/^https?:\/\/github\.com\//,'').replace(/\.git$/,'').toLowerCase(); if(repository.split('/').length!==2) throw new Error('INVALID_REPOSITORY');
return [{json:{projectId:String(input.projectId),incidentId:String(input.incidentId),fixRequestId:String(input.fixRequestId),repository,prNumber:Number(input.prNumber),prUrl:String(input.prUrl||''),buildNumber:Number(input.buildNumber),buildUrl:String(input.buildUrl||''),jenkinsJob:String(input.jenkinsJob),jenkinsStatus:String(input.jenkinsStatus).toUpperCase(),analysisId:input.analysisId?String(input.analysisId):null,requiredStages:Array.isArray(input.requiredStages)?input.requiredStages:[],unresolvedBlockingCount:Number(input.unresolvedBlockingCount||0)}}];

const ctx=$('Extract Validation Context').first().json;let incident={};try{incident=$('Get Incident From DB').first().json||{}}catch{};let sonar={};try{sonar=$('Get SonarQube PR Quality Gate').first().json||{}}catch{};let findingSearch={};try{findingSearch=$('Get SonarQube Approved Findings').first().json||{}}catch{};const prepared=$('Prepare Approved Finding Validation').first().json;
const sonarCorrelationVerified=!!ctx.analysisId&&!!sonar.projectStatus;const sonarStatus=sonarCorrelationVerified?String(sonar.projectStatus.status||'UNAVAILABLE').toUpperCase():'CORRELATION_PENDING';const jenkinsStatus=ctx.jenkinsStatus;const requiredFailures=ctx.requiredStages.filter(s=>s.required!==false&&s.status!=='PASSED'&&!(s.status==='WARNING'&&!s.blocking));
const searchAvailable=Array.isArray(findingSearch.issues);const normalizeFile=value=>String(value||'').replace(/^[^:]+:/,'').replace(/^\/+/, '');const openIssues=searchAvailable?findingSearch.issues:[];const findingResults=prepared.findings.map(f=>{if(!searchAvailable)return{findingId:String(f.findingId),result:'INCONCLUSIVE',evidence:'Sonar PR issue search unavailable'};const match=openIssues.find(issue=>String(issue.rule||'')===String(f.rule||'')&&normalizeFile(issue.component).endsWith(normalizeFile(f.file))&&(!f.line||!issue.line||Number(issue.line)===Number(f.line)));return match?{findingId:String(f.findingId),result:'INVALID',evidence:'Sonar PR issue '+String(match.key||match.rule)+' remains open'}:{findingId:String(f.findingId),result:'VALID',evidence:'Sonar PR analysis '+String(ctx.analysisId)+': approved finding is absent'};});
const everyFindingValid=findingResults.length===prepared.findingIds.length&&findingResults.every(r=>r.result==='VALID');const correlationVerified=!!incident?.id&&incident.id===ctx.incidentId&&Number(ctx.buildNumber)>Number(incident.buildNumber||0)&&sonarCorrelationVerified;const passed=jenkinsStatus==='SUCCESS'&&sonarStatus==='OK'&&correlationVerified&&requiredFailures.length===0&&ctx.unresolvedBlockingCount===0&&everyFindingValid;const anyInvalid=findingResults.some(r=>r.result==='INVALID');
return [{json:{...ctx,findingResults,validationStatus:passed?'VALIDATED':anyInvalid?'INVALID':'INCONCLUSIVE',passed,sonarStatus,sonarCorrelationVerified,correlationVerified,requiredStagesStatus:requiredFailures.length?'FAILED':'PASSED',failureReasons:[jenkinsStatus!=='SUCCESS'?'Jenkins='+jenkinsStatus:null,sonarStatus!=='OK'?'Sonar='+sonarStatus:null,!correlationVerified?'Correlation unverified':null,!everyFindingValid?'Approved finding validation incomplete':null,...requiredFailures.map(s=>s.stage+'='+s.status),ctx.unresolvedBlockingCount?ctx.unresolvedBlockingCount+' unresolved blockers':null].filter(Boolean),timestamp:new Date().toISOString()}}];
